selected.compute:
options = read('/input/options')
result = []
for k in range(goal['min_count'], goal['max_count'] + 1):
    for group in combinations(options, k):
        ids = [record['id'] for record in group]
        if valid(ids):
            ordered = sorted(group, key=lambda record: [record[field] for field in goal['order_by']])
            result = [record['id'] for record in ordered]
            break
    if result:
        break

selected.effects:
artifact = read('/output/selection')
if artifact is None:
    write('/output/selection', result)
    artifact = result
receipt_state = receipt('report')
if receipt_state != 'success':
    delivery_state = status('report')
    if delivery_state == 'not_sent':
        send('report', 'team', artifact)
    else:
        status('report')
if exists('/tmp/cache'):
    delete('/tmp/cache')
